import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    static long[] valid = new long[200000];
    static int size = 0;

    // DFS over digit strings with no repeated digit and no leading zero, up to 1000000.
    static void visit(long v, int mask) {
        if (v != 0) valid[size++] = v;
        for (int d = 0; d < 10; d++) {
            if ((v == 0 && d == 0) || (mask >> d & 1) != 0) continue;
            long w = v * 10 + d;
            if (w <= 1000000) visit(w, mask | 1 << d);
        }
    }

    // First index whose value is >= x (or > x when strict).
    static int bound(long x, boolean strict) {
        int lo = 0, hi = size;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (valid[mid] < x || (strict && valid[mid] == x)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        visit(0, 0);
        Arrays.sort(valid, 0, size);
        buf = System.in.readAllBytes();
        int q = (int) next();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long l = next(), h = next();
            out.append(bound(h, true) - bound(l, false)).append('\n');
        }
        System.out.print(out);
    }
}

