import (
	"bufio"
	"io"
	"os"
	"slices"
	"sort"
	"strconv"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

var valid []int64

// visit runs a DFS over digit strings with no repeated digit and no leading zero, up to 1000000.
func visit(v int64, mask int) {
	if v != 0 {
		valid = append(valid, v)
	}
	for d := 0; d < 10; d++ {
		if (v == 0 && d == 0) || mask>>d&1 == 1 {
			continue
		}
		if w := v*10 + int64(d); w <= 1000000 {
			visit(w, mask|1<<d)
		}
	}
}

func main() {
	visit(0, 0)
	slices.Sort(valid)
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	q := int(next())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		l, h := next(), next()
		hi := sort.Search(len(valid), func(k int) bool { return valid[k] > h })
		lo := sort.Search(len(valid), func(k int) bool { return valid[k] >= l })
		w.WriteString(strconv.Itoa(hi-lo) + "\n")
	}
}
